
create table nodes (
    ordinal serial primary key,
    nodeID bigint,
    nodeLAT numeric,
    nodeLON numeric,
    nodeNAME varchar,
    nodeAMENITY varchar
    );


create table ways (
    ordinal serial primary key,
    wayID bigint,
    typeWAY varchar,
    nameWAY varchar
    );


create table ways_nodes (
    ordinal serial primary key,
    wayID bigint,
    nodeID bigint,
    orderNODE int
    );

